const coverSvg=(t,logo)=>{const lines=t.titleEn.toUpperCase().replace(/\?|:/g,'').split(/\s+/);const groups=[];let line='';for(const word of lines){if((line+' '+word).trim().length>22){groups.push(line);line=word}else line=(line+' '+word).trim()}if(line)groups.push(line);const shown=groups.slice(0,4);return `<svg xmlns="http://www.w3.org/2000/svg" width="1774" height="887" viewBox="0 0 1774 887"><defs><linearGradient id="b" x2="1" y2="1"><stop stop-color="#fffdf8"/><stop offset="1" stop-color="#e8e5ff"/></linearGradient><linearGradient id="p" x2="1" y2="1"><stop stop-color="#5060df"/><stop offset="1" stop-color="#a083f4"/></linearGradient><filter id="s"><feDropShadow dx="0" dy="18" stdDeviation="18" flood-color="#453a86" flood-opacity=".18"/></filter></defs><rect width="1774" height="887" fill="url(#b)"/><rect x="76" y="64" width="420" height="50" rx="25" fill="#dce7ff"/><text x="100" y="97" font-family="Arial" font-size="19" font-weight="700" fill="#2457c7">${esc(t.catEn)}</text>${shown.map((x,i)=>`<text x="76" y="${205+i*76}" font-family="Arial Black,Arial" font-size="${x.length>20?58:66}" font-weight="900" fill="${i===1?'#315bdd':'#171424'}">${esc(x)}</text>`).join('')}<rect x="78" y="${245+shown.length*76}" width="90" height="8" rx="4" fill="#315bdd"/><text x="78" y="${305+shown.length*76}" font-family="Arial" font-size="25" fill="#403b52">Evidence first. Permission second. Readback always.</text><g transform="translate(1080 120)" filter="url(#s)"><circle cx="275" cy="290" r="275" fill="#d7d2ff"/><rect x="60" y="80" width="430" height="430" rx="54" fill="url(#p)"/><rect x="113" y="136" width="324" height="226" rx="30" fill="#fff"/><path d="M160 195h216M160 242h170M160 289h198" stroke="#5964df" stroke-width="18" stroke-linecap="round"/><circle cx="400" cy="120" r="72" fill="#ff91c6"/><path d="M370 120l21 21 42-50" fill="none" stroke="#fff" stroke-width="14" stroke-linecap="round" stroke-linejoin="round"/><path d="M125 422h300" stroke="#fff" stroke-width="30" stroke-linecap="round" opacity=".9"/></g><image href="${logo}" x="78" y="760" width="135" height="82" preserveAspectRatio="xMinYMid meet"/></svg>`};

const diagram=(t,zh=false)=>{const labs=zh?['事实','证据','决定','授权','回读']:['FACT','EVIDENCE','DECIDE','PERMISSION','READBACK'];return `<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="760" viewBox="0 0 1400 760"><rect width="1400" height="760" rx="34" fill="#17142f"/><text x="72" y="92" fill="#fff" font-family="Arial" font-size="38" font-weight="800">${esc(zh?t.titleZh:t.titleEn)}</text><path d="M130 380H1270" stroke="#5f56a4" stroke-width="10" stroke-linecap="round"/>${labs.map((x,i)=>`<g transform="translate(${145+i*277} 255)"><circle cy="125" r="62" fill="#383272" stroke="#ff4fa3" stroke-width="7"/><text y="136" text-anchor="middle" fill="#fff" font-family="Arial" font-size="30" font-weight="800">${i+1}</text><rect x="-105" y="218" width="210" height="72" rx="22" fill="#f3f0ff"/><text y="264" text-anchor="middle" fill="#231d43" font-family="Arial" font-size="19" font-weight="700">${x}</text></g>`).join('')}<text x="72" y="700" fill="#bcb6e8" font-family="Arial" font-size="18">WE MARKETING · OPERATOR FRAMEWORK</text></svg>`};

const faqSchema=body=>[...body.matchAll(/<h3>([^<]+)<\/h3><p>([^<]+)<\/p>/g)].slice(-6).map(([,name,text])=>({'@type':'Question',name,acceptedAnswer:{'@type':'Answer',text}}));
function page(t,en,zh){const date=`2026-08-${pad2(t.day)}`;const desc=t.excerptEn;const citations=t.sources.map(source);const schema={'@context':'https://schema.org','@graph':[{'@type':'BlogPosting',headline:t.titleEn,description:desc,inLanguage:'en-US',datePublished:date,dateModified:'2026-08-31',mainEntityOfPage:`${base}/blog/${t.slug}`,image:`${base}/blog/hero-${t.slug}-v1.png`,author:{'@type':'Organization',name:'WE Marketing'},publisher:{'@type':'Organization',name:'WE Marketing'},citation:citations},{'@type':'BlogPosting',headline:t.titleZh,description:t.excerptZh,inLanguage:'zh-CN',datePublished:date,dateModified:'2026-08-31',mainEntityOfPage:`${base}/blog/${t.slug}?lang=zh`,image:`${base}/blog/hero-${t.slug}-v1.png`,author:{'@type':'Organization',name:'WE Marketing'},publisher:{'@type':'Organization',name:'WE Marketing'},citation:citations},{'@type':'FAQPage',inLanguage:'en-US',mainEntity:faqSchema(en)},{'@type':'FAQPage',inLanguage:'zh-CN',mainEntity:faqSchema(zh)}]};return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><script>document.documentElement.dataset.lang=new URLSearchParams(location.search).get('lang')==='zh'?'zh':'en';document.documentElement.lang=document.documentElement.dataset.lang==='zh'?'zh-CN':'en'</script><title>${esc(t.titleEn)} | WE Marketing</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${base}/blog/${t.slug}"><link rel="alternate" hreflang="en-US" href="${base}/blog/${t.slug}"><link rel="alternate" hreflang="zh-CN" href="${base}/blog/${t.slug}?lang=zh"><link rel="alternate" hreflang="x-default" href="${base}/blog/${t.slug}"><meta property="og:type" content="article"><meta property="og:title" content="${esc(t.titleEn)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:image" content="${base}/blog/hero-${t.slug}-v1.png"><meta property="article:published_time" content="${date}"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">${JSON.stringify(schema)}</script><link rel="stylesheet" href="/blog/wem-editorial-system.css"><link rel="stylesheet" href="/blog/wem-editorial-article.css"><link rel="stylesheet" href="/blog/wem-august-2026-article.css?v=20260831-01"></head><body><main class="wrap"><a href="/blog">← Blog</a><article lang="en"><p>${esc(t.catEn)}</p><h1>${esc(t.titleEn)}</h1><p>WE Marketing Team · Aug ${t.day}, 2026 · 15 min read</p><img class="hero" src="/blog/hero-${t.slug}-v1.png" alt="${esc(t.titleEn)} editorial cover"><figure><img src="/blog/${t.slug}-operating-system-v1.svg" alt="${esc(t.titleEn)} operating system"><figcaption>WEM separates fact, evidence, decision, permission, and terminal readback.</figcaption></figure>${en}</article><article lang="zh-CN"><p>${esc(t.catZh)}</p><h1>${esc(t.titleZh)}</h1><p>WE Marketing Team · 2026 年 8 月 ${t.day} 日 · 15 分钟阅读</p><img class="hero" src="/blog/hero-${t.slug}-v1.png" alt="${esc(t.titleZh)}编辑封面"><figure><img src="/blog/${t.slug}-operating-system-zh-v1.svg" alt="${esc(t.titleZh)}运营系统"><figcaption>WEM 把事实、证据、决定、授权与最终回读分开。</figcaption></figure>${zh}</article></main><script src="/blog/wem-editorial-enhance.js" defer></script></body></html>`}

