await fs.copyFile(path.join(repo,'ui_kits/website/assets/we-logo.png'),path.join(patch,'assets/we-logo.png'));
const logo=`data:image/png;base64,${(await fs.readFile(path.join(repo,'ui_kits/website/assets/we-logo.png'))).toString('base64')}`;
await fs.writeFile(path.join(blog,'wem-august-2026-article.css'),style);
const counts=[];
for(const t of topics){const en=articleEn(t),zh=articleZh(t);const enWords=strip(en).split(/\s+/).length,zhChars=(strip(zh).match(/[\u3400-\u9fff]/g)||[]).length;if(enWords<1300)throw new Error(`${t.slug} English too short ${enWords}`);if(zhChars<1800)throw new Error(`${t.slug} Chinese too short ${zhChars}`);if(/[—]/.test(en+zh))throw new Error(`${t.slug} em dash`);await fs.writeFile(path.join(blog,`${t.slug}.html`),page(t,en,zh));await fs.writeFile(path.join(blog,`hero-${t.slug}-v1.svg`),coverSvg(t,logo));await fs.writeFile(path.join(blog,`${t.slug}-operating-system-v1.svg`),diagram(t));await fs.writeFile(path.join(blog,`${t.slug}-operating-system-zh-v1.svg`),diagram(t,true));counts.push({slug:t.slug,enWords,zhChars});}

const fetchText=async url=>{const r=await fetch(url);if(!r.ok)throw new Error(`${url} ${r.status}`);return r.text()};
let list=await fs.readFile(path.join(repo,'outputs/patches/2026-08-31-training28/BlogList.jsx'),'utf8');
for(const t of [...topics].reverse()){const row=`{slug:'${t.slug}',tags:['tiktok-shop','shop-operations'],cat:{en:'${t.catEn}',zh:'${t.catZh}'},title:{en:'${t.titleEn.replaceAll("'","\\'")}',zh:'${t.titleZh}'},excerpt:{en:'${t.excerptEn.replaceAll("'","\\'")}',zh:'${t.excerptZh}'},date:{en:'Aug ${t.day}, 2026',zh:'2026 年 8 月 ${t.day} 日'},read:{en:'15 min read',zh:'15 分钟阅读'},image:'hero-${t.slug}-v1.png'},`;if(!list.includes(`slug:'${t.slug}'`))list=list.replace(/(const BLOG_POSTS = \[\{slug:'tiktok-shop-live-assortment'[\s\S]*?\},)(?=\{slug:'tiktok-shop-live-preheat-system')/,`$1${row}`);}
await fs.writeFile(path.join(patch,'BlogList.jsx'),list);const babelCode=await fs.readFile(path.join(repo,'.cache/babel-standalone-7.29.0.min.js'),'utf8');const sandbox={};vm.createContext(sandbox);vm.runInContext(babelCode,sandbox);const compiled=sandbox.Babel.transform(list,{presets:[['react',{runtime:'classic'}]],comments:false,compact:true,minified:true,sourceType:'script'}).code;await fs.writeFile(path.join(patch,'BlogList.compiled.js'),compiled+'\n');
let index=await fetchText(`${base}/blog`);index=index.replace(/BlogList\.compiled\.js\?v=[^"']+/,'BlogList.compiled.js?v=20260831-backfill-01');await fs.writeFile(path.join(patch,'blog.html'),index);
let sitemap=await fetchText(`${base}/sitemap.xml`);for(const t of topics){const date=`2026-08-${pad2(t.day)}`;if(!sitemap.includes(`/blog/${t.slug}</loc>`))sitemap=sitemap.replace('</urlset>',`<url><loc>${base}/blog/${t.slug}</loc><lastmod>${date}</lastmod></url></urlset>`);}await fs.writeFile(path.join(patch,'sitemap.xml'),sitemap);
let llms=await fetchText(`${base}/llms.txt`);for(const t of topics)if(!llms.includes(`${base}/blog/${t.slug}`))llms+=`\n- ${t.titleEn}: ${base}/blog/${t.slug}\n  - Chinese: ${base}/blog/${t.slug}?lang=zh\n`;await fs.writeFile(path.join(patch,'llms.txt'),llms);

let enhancer=await fetchText(`${base}/blog/wem-editorial-enhance.js`);const protectedSlugs=['tiktok-shop-open-collaboration-product-fit','tiktok-shop-affiliate-commission-change','measure-tiktok-shop-partner-performance','tiktok-shop-probation-growth-plan','weekly-tiktok-shop-operating-review','tiktok-shop-live-first-five-sessions-learning-system','tiktok-shop-live-preheat-system','tiktok-shop-live-assortment',...topics.map(t=>t.slug)];
for(const s of protectedSlugs)if(!new RegExp(`coverAlreadyIncludesCopy[\\s\\S]*?'${s}'[\\s\\S]*?\\]`).test(enhancer))enhancer=enhancer.replace(/(const coverAlreadyIncludesCopy = new Set\(\[)/,`$1\n    '${s}',`);
enhancer+=`\n/* Aug 15-31 source-note normalization */\naddEventListener('DOMContentLoaded',()=>{document.querySelectorAll('article h2').forEach(h=>{if(!/^(Source notes|Source notes and|来源说明)/i.test(h.textContent.trim()))return;h.textContent=/^来源说明/.test(h.textContent.trim())?'来源说明':'Source notes';const parent=h.parentElement;if(parent&&parent.tagName==='SECTION'){parent.classList.add('wem-source-notes');return;}const section=document.createElement('section');section.className='wem-source-notes';const nodes=[];let cursor=h.nextSibling;while(cursor&&!(cursor.nodeType===1&&cursor.tagName==='H2')){nodes.push(cursor);cursor=cursor.nextSibling;}h.before(section);section.append(h,...nodes);});});\n`;
await fs.writeFile(path.join(blog,'wem-editorial-enhance.js'),enhancer);

